const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  const provinceName = 'Sindh';
  const countryName = 'Pakistan';

  // Define the geometry for Sindh province
  const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1');
  const sindh = gaul.filter(ee.Filter.and(
    ee.Filter.eq('ADM0_NAME', countryName),
    ee.Filter.eq('ADM1_NAME', provinceName)
  )).first();

  if (!sindh) {
    console.log(`Error: Could not find ${provinceName} in ${countryName}.`);
    console.log("D");
    return;
  }

  const geometry = sindh.geometry();

  // Define date ranges (+/- 5 days from Sep 21)
  const date2019_start = '2019-09-16';
  const date2019_end = '2019-09-26';
  const date2020_start = '2020-09-16';
  const date2020_end = '2020-09-26';

  const S1_SPECKLE_FILTER_WINDOW_SIZE = 7;
  const S1_WATER_THRESHOLD_DB = -18; // Threshold for water detection in dB

  // Function to apply speckle filter
  function applySpeckleFilter(image) {
    return image.focal_median(S1_SPECKLE_FILTER_WINDOW_SIZE, 'square', 'pixels');
  }

  // Function to get and process Sentinel-1 images
  function getSentinel1Water(startDate, endDate, geometry) {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .select('VV');

    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No Sentinel-1 images found for ${startDate} to ${endDate}.`);
      return null;
    }

    // Apply speckle filter and mosaic
    let image = collection.map(applySpeckleFilter).median();

    // Convert to dB
    image = ee.Image.cat(image.unitScale(0, 1).log10().multiply(10).rename('VV_db'));

    // Create water mask
    const waterMask = image.select('VV_db').lt(S1_WATER_THRESHOLD_DB);

    // Calculate water area (square kilometers)
    const waterAreaSqKm = waterMask.multiply(ee.Image.pixelArea()).divide(1e6)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: 100, // Sentinel-1 resolution is 10m, using 100m for faster calc
        maxPixels: 1e9,
        tileScale: 16
      }).get('VV_db'); // band name from pixelArea is the same as the input band

    return {
      area: waterAreaSqKm,
      imageCount: collectionSize
    };
  }

  // 2. Data Acquisition & Check
  console.log(`Processing for Sindh province (${countryName}).`);

  const s1_2019 = getSentinel1Water(date2019_start, date2019_end, geometry);
  const s1_2020 = getSentinel1Water(date2020_start, date2020_end, geometry);

  if (!s1_2019 || !s1_2020) {
    console.log("C1");
    return;
  }

  const area2019 = await s1_2019.area.getInfo();
  const area2020 = await s1_2020.area.getInfo();

  // 3. Validation and Fallback Checks
  if (area2019 === null || isNaN(area2019) || area2020 === null || isNaN(area2020)) {
    console.log("Calculation of water area resulted in None or NaN.");
    console.log("C3");
    return;
  }

  // Check for C2: No valid pixels (water mask might result in 0 pixels,
  // but if the base image has 0 pixels, that's a problem).
  // A non-null area means that pixels were processed. An area of 0 means no water was detected, which is a valid result for A/B.
  // We've already checked for collection size for C1.

  console.log(`2019 Images: ${s1_2019.imageCount}, 2019 Water Area: ${area2019.toFixed(2)} sq km`);
  console.log(`2020 Images: ${s1_2020.imageCount}, 2020 Water Area: ${area2020.toFixed(2)} sq km`);

  // 4. Comparison and Final Answer
  if (area2020 > area2019) {
    console.log("A");
  } else {
    console.log("B");
  }
}

initEE();
